import os,pathlib,hashlib,json,base64,subprocess
assert os.geteuid()==0
base=pathlib.Path('/opt/nan-relay')
expected={'sessions.mjs':'457e86472adce2f1fdd2dfa82759578a56f7d72f0c5e5ee18e53999a26d0682d','api-relay.js':'481f00410b87f30ee467183db7121175d37c010be5b2c23891a0a19e63b4579d','store.js':'12157d8ccf8b1ec4ffd4d0af9b5b846650ec20aac748bcc51ad087e119922dcd'}
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert all(sha(base/n)==h for n,h in expected.items())
pid=lambda:subprocess.check_output(['systemctl','show','enclave-api-relay.service','-p','MainPID','--value'],text=True).strip()
before=pid(); assert before=='228946'
stage=pathlib.Path('/opt/enclave-funding-staged/quarantine-r1-20261028')
assert not os.path.lexists(stage)
stage.mkdir(mode=0o755)
FILES={'fee-policy.mjs': {'sha256': '32bcf03ea52db9be70d86e957dd440c1697daf0eaeab79f732378002d4f2bcfd', 'base64': ''}, 'funding-abi.mjs': {'sha256': '6bb37e658aca45fd416d5ea17dda3109e1b41791e674976a60425d579f485cd7', 'base64': ''}, 'funding-activation.mjs': {'sha256': '7554454dbe091f4bcc7ef8e15ac5dd8082c8be6d94256f52b1c8fadcfc198645', 'base64': ''}, 'funding-route.mjs': {'sha256': '1989f3ebf88833ac492e4f121ff33d564b1798eae1e5239b1aae444b63b572cd', 'base64': ''}, 'sessions.mjs': {'sha256': '483b1c5ef29d83c937a5fd5b15ea3b2e940025d76706a1c5a63867f33c55c4e3', 'base64': ''}}
for n,d in FILES.items():
 assert '/' not in n
 b=base64.b64decode(d['base64']);assert hashlib.sha256(b).hexdigest()==d['sha256']
 with (stage/n).open('xb') as f:f.write(b);f.flush();os.fsync(f.fileno())
 os.chmod(stage/n,0o644);assert sha(stage/n)==d['sha256']
for n in ['node_modules','sessions-abi.mjs','snp-verify.mjs']:
 assert (base/n).exists();os.symlink(base/n,stage/n)
fd=os.open(stage,os.O_RDONLY|os.O_DIRECTORY);os.fsync(fd);os.close(fd)
js="""import assert from 'node:assert/strict';
import {WRITE_QUARANTINE,createSessionsService,TxQueue} from 'file:///opt/enclave-funding-staged/quarantine-r1-20261028/sessions.mjs';
assert.equal(WRITE_QUARANTINE.on,true);
let rpc=0,send=0,writes=0;
const pc=new Proxy({}, {get(){return ()=>{rpc++;throw Error('unexpected RPC')}}});
const svc=createSessionsService({pc,wc:{chain:{id:8453},sendTransaction(){send++;throw Error('unexpected send')}},
account:{address:'0x3333333333333333333333333333333333333333'},chainId:8453,factory:'0x4444444444444444444444444444444444444444',
store:{data:{},saveSoon(){writes++},flush(){writes++}},journal:{data:{txs:[]},saveSoon(){writes++},flush(){writes++}},log(){},alert(){}});
for(const path of ['/open','/owner','/end','/execute','/attest','/funding/open','/funding/execute','/funding/owner'])
 await assert.rejects(svc.route('POST',path,{}),{code:'write_quarantine',status:503});
await assert.rejects(svc.queue.send({}),{code:'write_quarantine'});
await svc.keeperOnce();assert.equal(rpc,0);assert.equal(send,0);assert.equal(writes,0);
assert.equal((await svc.route('GET','/config')).relayer,'0x3333333333333333333333333333333333333333');
console.log(JSON.stringify({quarantine:true,refusedRoutes:8,rpc,send,writes,legacyRead:true}));"""
r=subprocess.run(['runuser','-u','enclave-api-relay','--','env','SESSIONS_WRITE_QUARANTINE=1','node','--input-type=module','-e',js],check=True,text=True,capture_output=True,timeout=30)
assert all(sha(base/n)==h for n,h in expected.items()) and pid()==before
print(json.dumps({'stage':str(stage),'readback':{n:sha(stage/n) for n in FILES},'serviceUserSmoke':json.loads(r.stdout),'activePid':before,'originalSourcesUnchanged':True,'activeImportOrRestart':False}))
